const { test } = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const { execFileSync } = require('node:child_process');

const ROOT = path.join(__dirname, '..');
const SPDX_ID = 'AGPL-3.0-only';
const HEADER = `SPDX-License-Identifier: ${SPDX_ID}`;

// Source files that must carry the header. next-env.d.ts is generated by Next.
const SOURCE = /\.(ts|tsx|js|mjs|cjs|py|css|yml|yaml)$|(^|\/)Dockerfile$/;
const EXEMPT = new Set(['frontend/next-env.d.ts']);

function projectFiles() {
  // Tracked plus new, not-ignored files, so a missing header fails before commit.
  const out = execFileSync('git', ['ls-files', '--cached', '--others', '--exclude-standard', '-z'], {
    cwd: ROOT,
    encoding: 'utf8',
  });
  return [...new Set(out.split('\0').filter(Boolean))].filter((file) => fs.existsSync(path.join(ROOT, file)));
}

test('every source file declares the project license', () => {
  const missing = projectFiles()
    .filter((file) => SOURCE.test(file) && !EXEMPT.has(file))
    .filter((file) => {
      // The header sits on the first line, or the second after a shebang or a
      // Dockerfile parser directive.
      const head = fs.readFileSync(path.join(ROOT, file), 'utf8').split('\n', 2);
      return !head.some((line) => line.includes(HEADER));
    });
  assert.deepEqual(missing, [], `Add "${HEADER}" as the first comment in:\n  ${missing.join('\n  ')}`);
});

test('LICENSE holds the GNU AGPL version 3 text', () => {
  const text = fs.readFileSync(path.join(ROOT, 'LICENSE'), 'utf8');
  assert.match(text, /^\s*GNU AFFERO GENERAL PUBLIC LICENSE\n\s*Version 3, 19 November 2007\n/);
  assert.match(text, /END OF TERMS AND CONDITIONS/);
});

test('package manifests and lockfiles declare the same license', () => {
  for (const dir of ['.', 'backend', 'frontend']) {
    const manifest = JSON.parse(fs.readFileSync(path.join(ROOT, dir, 'package.json'), 'utf8'));
    assert.equal(manifest.license, SPDX_ID, `${dir}/package.json`);
    const lock = JSON.parse(fs.readFileSync(path.join(ROOT, dir, 'package-lock.json'), 'utf8'));
    assert.equal(lock.packages[''].license, SPDX_ID, `${dir}/package-lock.json`);
  }
});

test('published images are labelled with the project license', () => {
  for (const dir of ['backend', 'frontend']) {
    const dockerfile = fs.readFileSync(path.join(ROOT, dir, 'Dockerfile'), 'utf8');
    assert.match(dockerfile, new RegExp(`org\\.opencontainers\\.image\\.licenses="${SPDX_ID}"`), `${dir}/Dockerfile`);
  }
});
